// text.mjs — 文本与 HTML 工具（零依赖，ESM，不使用正则）。
// 本文件不得依赖其他本地模块。

const NAMED_ENTITIES = new Map([
  ['amp', '&'],
  ['lt', '<'],
  ['gt', '>'],
  ['quot', '"'],
  ['apos', "'"],
  ['nbsp', ' '],
  ['copy', '©'],
  ['reg', '®'],
  ['trade', '™'],
  ['hellip', '…'],
  ['mdash', '—'],
  ['ndash', '–'],
]);

function isUnicodeWhitespaceChar(ch) {
  // 单字符 trim 可覆盖 NBSP 等 Unicode 空白。
  return ch.trim() === '';
}

/**
 * CRLF/CR → LF；tab 按 4 列制表位展开（对齐到 4 的倍数列，列从行首计）。
 */
export function normalizeText(value) {
  const input = String(value);
  let out = '';
  let col = 0;
  let i = 0;
  const n = input.length;
  while (i < n) {
    const ch = input[i];
    if (ch === '\r') {
      if (i + 1 < n && input[i + 1] === '\n') {
        i += 1;
      }
      out += '\n';
      col = 0;
    } else if (ch === '\n') {
      out += '\n';
      col = 0;
    } else if (ch === '\t') {
      const spaces = 4 - (col % 4);
      out += '    '.slice(0, spaces);
      col += spaces;
    } else {
      out += ch;
      col += 1;
    }
    i += 1;
  }
  return out;
}

/**
 * 行为空行：空或仅含 Unicode 空白字符。
 */
export function isBlankLine(line) {
  const s = String(line);
  for (let i = 0; i < s.length; i += 1) {
    if (!isUnicodeWhitespaceChar(s[i])) {
      return false;
    }
  }
  return true;
}

/**
 * 去除文本首尾的空白行（中间的空白行保留）。
 */
export function stripOuterBlankLines(text) {
  const lines = String(text).split('\n');
  let start = 0;
  let end = lines.length;
  while (start < end && isBlankLine(lines[start])) {
    start += 1;
  }
  while (end > start && isBlankLine(lines[end - 1])) {
    end -= 1;
  }
  return lines.slice(start, end).join('\n');
}

/**
 * 统计行首可剥空白（空格与 NBSP）数量。
 */
export function countLeadingSpaces(line) {
  const s = String(line);
  let count = 0;
  while (count < s.length) {
    const ch = s[count];
    if (ch === ' ' || ch === ' ') {
      count += 1;
    } else {
      break;
    }
  }
  return count;
}

/**
 * 代码/属性转义：& < > " 全部转义。
 */
export function escapeHtmlAll(value) {
  const s = String(value);
  let out = '';
  for (let i = 0; i < s.length; i += 1) {
    const ch = s[i];
    if (ch === '&') {
      out += '&amp;';
    } else if (ch === '<') {
      out += '&lt;';
    } else if (ch === '>') {
      out += '&gt;';
    } else if (ch === '"') {
      out += '&quot;';
    } else {
      out += ch;
    }
  }
  return out;
}

/**
 * 属性值转义（与 escapeHtmlAll 一致：& < > " 全部转义）。
 */
export function escapeAttribute(value) {
  return escapeHtmlAll(value);
}

function isAsciiDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

function isHexDigit(ch) {
  return isAsciiDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

/**
 * 尝试在 text[index]（应为 '&'）处解析一个 HTML 实体。
 * 返回 { raw, decoded, end }（end 为实体之后的位置），不是合法实体时返回 null。
 * 支持命名实体（见 NAMED_ENTITIES）与十进制（&#123;）/十六进制（&#x1F;）数字实体。
 */
export function parseEntityAt(text, index) {
  const s = String(text);
  const n = s.length;
  if (index < 0 || index >= n || s[index] !== '&') {
    return null;
  }
  let i = index + 1;
  if (i >= n) {
    return null;
  }
  if (s[i] === '#') {
    // 数字实体
    i += 1;
    let isHex = false;
    if (i < n && (s[i] === 'x' || s[i] === 'X')) {
      isHex = true;
      i += 1;
    }
    const digitStart = i;
    while (i < n && (isHex ? isHexDigit(s[i]) : isAsciiDigit(s[i]))) {
      i += 1;
    }
    if (i === digitStart || i >= n || s[i] !== ';') {
      return null;
    }
    const digits = s.slice(digitStart, i);
    let codePoint;
    if (isHex) {
      codePoint = 0;
      for (let k = 0; k < digits.length; k += 1) {
        const c = digits[k];
        let v;
        if (isAsciiDigit(c)) {
          v = c.charCodeAt(0) - 48;
        } else if (c >= 'a' && c <= 'f') {
          v = c.charCodeAt(0) - 87;
        } else {
          v = c.charCodeAt(0) - 55;
        }
        codePoint = codePoint * 16 + v;
        if (codePoint > 0x10ffff) {
          return null;
        }
      }
    } else {
      codePoint = 0;
      for (let k = 0; k < digits.length; k += 1) {
        codePoint = codePoint * 10 + (digits[k].charCodeAt(0) - 48);
        if (codePoint > 0x10ffff) {
          return null;
        }
      }
    }
    let decoded;
    try {
      decoded = String.fromCodePoint(codePoint);
    } catch {
      return null;
    }
    return { raw: s.slice(index, i + 1), decoded, end: i + 1 };
  }
  // 命名实体：字母数字组成，分号结尾
  const nameStart = i;
  while (i < n && (isAsciiLetter(s[i]) || isAsciiDigit(s[i]))) {
    i += 1;
  }
  if (i === nameStart || i >= n || s[i] !== ';') {
    return null;
  }
  const name = s.slice(nameStart, i);
  if (!NAMED_ENTITIES.has(name)) {
    return null;
  }
  return { raw: s.slice(index, i + 1), decoded: NAMED_ENTITIES.get(name), end: i + 1 };
}

/**
 * 普通文本转义：裸 & → &amp;，合法实体（&name; &#123; &#x1F;）整体保留，< > 转义。
 */
export function escapeTextPreservingEntities(value) {
  const s = String(value);
  let out = '';
  let i = 0;
  while (i < s.length) {
    const ch = s[i];
    if (ch === '&') {
      const entity = parseEntityAt(s, i);
      if (entity !== null) {
        out += entity.raw;
        i = entity.end;
      } else {
        out += '&amp;';
        i += 1;
      }
    } else if (ch === '<') {
      out += '&lt;';
      i += 1;
    } else if (ch === '>') {
      out += '&gt;';
      i += 1;
    } else {
      out += ch;
      i += 1;
    }
  }
  return out;
}

/**
 * 解码字符串中所有可识别实体；无法识别的 & 原样保留。
 */
export function decodeEntities(value) {
  const s = String(value);
  let out = '';
  let i = 0;
  while (i < s.length) {
    if (s[i] === '&') {
      const entity = parseEntityAt(s, i);
      if (entity !== null) {
        out += entity.decoded;
        i = entity.end;
        continue;
      }
    }
    out += s[i];
    i += 1;
  }
  return out;
}

/**
 * NFKD 规范化后删除所有非 ASCII 字符（效果如 Python 的 encode('ascii', 'ignore')）。
 */
export function asciiFold(value) {
  const normalized = String(value).normalize('NFKD');
  let out = '';
  for (const ch of normalized) {
    if (ch.codePointAt(0) <= 0x7f) {
      out += ch;
    }
  }
  return out;
}

/**
 * 序列化属性（对象或 Map）：按属性名字典序输出 `k="v"` 列表，空格连接。
 * 值为 null/undefined 时跳过该属性；其他值经 String() 后按属性规则转义。
 */
export function serializeAttributes(attrs) {
  if (attrs === null || attrs === undefined) {
    return '';
  }
  const entries = [];
  if (attrs instanceof Map) {
    for (const [key, val] of attrs) {
      if (val === null || val === undefined) {
        continue;
      }
      entries.push([String(key), String(val)]);
    }
  } else {
    for (const key of Object.keys(attrs)) {
      const val = attrs[key];
      if (val === null || val === undefined) {
        continue;
      }
      entries.push([String(key), String(val)]);
    }
  }
  entries.sort((a, b) => {
    if (a[0] < b[0]) {
      return -1;
    }
    if (a[0] > b[0]) {
      return 1;
    }
    return 0;
  });
  const parts = [];
  for (const [key, val] of entries) {
    parts.push(key + '="' + escapeAttribute(val) + '"');
  }
  return parts.join(' ');
}

