node --input-type=module -e "
import * as t from '/output/lib/text.mjs';
const eq = (a, b, name) => { if (a !== b) { console.error('FAIL', name, JSON.stringify(a), '!==', JSON.stringify(b)); process.exitCode = 1; } else console.log('ok', name); };
eq(t.normalizeText('a\r\nb\rc\tX'), 'a\nb\nc   X', 'normalize basic');
eq(t.normalizeText('ab\tX'), 'ab  X', 'tab to col4');
eq(t.normalizeText('abcd\tX'), 'abcd    X', 'tab at multiple of 4');
eq(t.isBlankLine(''), true, 'blank empty');
eq(t.isBlankLine('   '), true, 'blank nbsp');
eq(t.isBlankLine(' x '), false, 'not blank');
eq(t.stripOuterBlankLines('\n\n  \nhello\n\n'), 'hello', 'strip outer');
eq(t.stripOuterBlankLines('a\n\nb'), 'a\n\nb', 'keep inner');
eq(t.countLeadingSpaces('    x'), 4, 'leading spaces+nbsp');
eq(t.countLeadingSpaces('\tx'), 0, 'tab not counted');
eq(t.escapeHtmlAll('<a & \"b\">'), '&lt;a &amp; &quot;b&quot;&gt;', 'escape all');
eq(t.escapeAttribute('a\"b&c'), 'a&quot;b&amp;c', 'escape attr');
eq(t.escapeTextPreservingEntities('a & b &amp; &#123; &#x1F; &bogus; <x>'), 'a &amp; b &amp; &#123; &#x1F; &amp;bogus; &lt;x&gt;', 'preserve entities');
const e1 = t.parseEntityAt('&amp;x', 0); eq(JSON.stringify(e1), JSON.stringify({raw:'&amp;',decoded:'&',end:5}), 'parse named');
const e2 = t.parseEntityAt('&#65;', 0); eq(e2.decoded, 'A', 'parse dec');
const e3 = t.parseEntityAt('&#x41;', 0); eq(e3.decoded, 'A', 'parse hex');
eq(t.parseEntityAt('&nope;', 0), null, 'parse unknown null');
eq(t.parseEntityAt('&amp', 0), null, 'parse missing semicolon');
eq(t.decodeEntities('&lt;a&gt;&copy;&bad;&'), '<a>©&bad;&', 'decode');
eq(t.asciiFold('Café — naïve'), 'Cafe  naive', 'asciiFold');
eq(t.serializeAttributes({b:'2', a:'1', c:null}), 'a=\"1\" b=\"2\"', 'attrs object sorted');
eq(t.serializeAttributes(new Map([['z','<'],['a','x\"y']])), 'a=\"x&quot;y\" z=\"&lt;\"', 'attrs map sorted+escaped');
eq(t.serializeAttributes({a:''}), 'a=\"\"', 'empty value');
console.log('DONE');
"
